def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c]==4:
                y,x=r-1,c+1
                while y>=0 and x<w and grid[y][x]!=5:
                    out[y][x]=4
                    y-=1; x+=1
    return out

